package models

import "time"

// Notification is a merchant-facing in-app event record.
// Currently two types are generated by the WhatsApp pipeline:
//   - "new_order"     — a customer completed checkout
//   - "payment_proof" — a customer submitted a bank transfer screenshot
//
// Records are created by createNotification() in whatsapp/notification_helper.go
// and consumed by GetNotifications in handlers/chat_handler.go.
type Notification struct {
	ID         uint      `json:"id" gorm:"primaryKey"`
	BusinessID uint      `json:"business_id" gorm:"not null;index"`
	Type       string    `json:"type" gorm:"not null"` // "new_order" | "payment_proof"
	Title      string    `json:"title" gorm:"not null"`
	Body       string    `json:"body" gorm:"type:text"`
	RefID      uint      `json:"ref_id"`                       // order.ID or proof.ID
	IsRead     bool      `json:"is_read" gorm:"default:false"` // merchant dismissal
	CreatedAt  time.Time `json:"created_at"`
}
